const main=$('#main');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0).toLocaleString('zh-CN',{maximumFractionDigits:2});
const fmt=v=>Number(v||0).toFixed(2);
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`;
const icons={arrow:'↗',next:'→',back:'←'};
let caseSelections={},activeReadId=null,suspendReading=false,dockObserver=null,avatarEditor=null;
if('scrollRestoration' in history)history.scrollRestoration='manual';
let memory={},storageFailed=false,badStorage={},brokenKeys=new Set();
function getStore(key,fallback){try{const raw=localStorage.getItem('ga:'+key);let value;const valid=v=>v==null||(['notes','trash'].includes(key)?Array.isArray(v)&&v.every(n=>n&&typeof n.id==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(n.id)&&typeof n.body==='string'&&typeof n.title==='string'):key==='progress'?typeof v==='object'&&!Array.isArray(v)&&Object.values(v).every(p=>p&&Number.isFinite(p.percent)&&p.percent>=0&&p.percent<=100&&Number.isFinite(p.scroll)&&p.scroll>=0):key==='sessions'?typeof v==='object'&&!Array.isArray(v)&&Object.entries(v).every(([id,s])=>/^[a-zA-Z0-9_-]{1,100}$/.test(id)&&s&&typeof s==='object'&&typeof s.token==='string'&&typeof s.agentToken==='string'&&typeof s.name==='string'):true);try{value=JSON.parse(raw);if(!valid(value))throw new Error('shape');return value??fallback;}catch{badStorage[key]=raw;brokenKeys.add(key);try{value=JSON.parse(localStorage.getItem('ga:recovered:'+key));return valid(value)?value??fallback:fallback;}catch{return fallback;}}}catch{storageFailed=true;return memory[key]??fallback;}}
function saveStore(key,value){memory[key]=value;try{localStorage.setItem((brokenKeys.has(key)?'ga:recovered:':'ga:')+key,JSON.stringify(value));return true;}catch{storageFailed=true;toast('本机存储不可用，本次修改暂存内存。请导出备份。',true);return false;}}
const validRecord=v=>v&&typeof v==='object'&&!Array.isArray(v);
const safeId=v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{1,100}$/.test(v);
let rawProgress=getStore('progress',{}),rawNotes=getStore('notes',[]),rawSessions=getStore('sessions',{});
for(const [key,v,valid] of [['progress',rawProgress,validRecord(rawProgress)],['notes',rawNotes,Array.isArray(rawNotes)&&rawNotes.every(n=>n&&safeId(n.id)&&typeof n.body==='string'&&typeof n.title==='string')],['sessions',rawSessions,validRecord(rawSessions)]]){if(!valid){brokenKeys.add(key);badStorage[key]=v;}}
let corruptedStorage=brokenKeys.size>0;
let progress=validRecord(rawProgress)?rawProgress:{},notes=Array.isArray(rawNotes)?rawNotes.filter(n=>n&&safeId(n.id)&&typeof n.body==='string'&&typeof n.title==='string'):[],sessions=validRecord(rawSessions)?rawSessions:{},config=null,currentState=null,pollId=null,globe=null,route='',viewKey='',serverOffset=0,autoRotate=!matchMedia('(prefers-reduced-motion: reduce)').matches;
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500);}
function go(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
function button(label,action,cls='button'){return `<button class="${cls}" data-action="${action}">${label}</button>`;}
function link(label,path,cls='text-link'){return `<a class="${cls}" href="#/${path}">${label}</a>`;}
function sectionLabel(){return '';}
function readPct(){return Math.round(chapters.reduce((s,c)=>s+(progress[c.id]?.percent||0),0)/chapters.length);}
function header(active){$('#site-header').innerHTML=`<a href="#/home" class="brand" aria-label="增长黑客首页"><span class="brand-mark">G<span>↗</span></span><span>增长黑客</span></a><nav aria-label="主导航"><a href="#/map" ${active==='map'||active==='read'?'aria-current="page"':''}>阅读地图</a><a href="#/lab" ${active==='lab'?'aria-current="page"':''}>增长实验室</a><a href="#/cases" ${active==='cases'?'aria-current="page"':''}>案例拆解</a><a href="#/notes" ${active==='notes'?'aria-current="page"':''}>阅读札记 <span class="note-count">${notes.length}</span></a></nav><a href="#/tavern" class="header-tavern">增长酒馆 <span>↗</span></a>`;}
function footer(){ $('#site-footer').innerHTML=`<p class="footer-source">《增长黑客》交互阅读<br><span>${bookMeta.authors} · 中信2018年中文版</span></p><nav class="footer-links" aria-label="页脚导航"><a href="#/map">阅读地图</a><a href="#/notes">我的札记</a><a href="#/tavern">增长酒馆</a></nav><p class="footer-note">学习型二次解读，游戏规则为教学改编。</p>`; }
function home(){const resume=chapters.find(c=>(progress[c.id]?.percent||0)>0&&(progress[c.id]?.percent||0)<100)||chapters[0];main.innerHTML=`<div class="page home-page"><section class="home-hero"><div class="hero-copy"><h1>增长黑客</h1><p class="hero-description">读懂增长背后的方法，动手做几次实验，再和自己的 Agent 经营一家公司。</p><div class="hero-actions">${link('开始阅读 →','map','button solid')}${link('进入增长酒馆','tavern','button outline')}</div><p class="book-byline">${bookMeta.authors}<br><span>${bookMeta.edition}</span></p></div><div class="hero-art"><img src="./assets/book-hero.webp" alt="朱红折纸台阶向上延伸，人物沿路径探索" width="1440" height="960" fetchpriority="high"></div></section><section class="home-path"><div><h2>从一个问题开始</h2><p class="muted">可以顺着读，也可以直接试。</p></div><div class="path-list"><a href="#/map"><div><h3>读一篇</h3><p>理解用户、激活、留存与增长实验。</p></div><b>↗</b></a><a href="#/lab"><div><h3>做个实验</h3><p>调整一个变量，看清结果为什么改变。</p></div><b>↗</b></a><a href="#/tavern"><div><h3>经营一局</h3><p>四席、六回合，和自己的 Agent 一起决策。</p></div><b>↗</b></a></div></section><section class="reading-resume"><h3>${readPct()>0?'继续上次的阅读':'翻开第一篇'}</h3><div class="resume-track"><i style="width:${readPct()}%"></i></div><span>${readPct()}% 已读</span>${link('继续阅读 →',`read/${resume.id}`)}</section></div>`;}
function mapPage(){main.innerHTML=`<div class="page map-page"><div class="page-heading"><div><h1>阅读地图</h1><p>六个主题，按你关心的问题进入。</p></div><div class="map-landscape"><img src="./assets/figma/landscape.png" alt="墨色地景与朱红太阳" width="2172" height="724"></div></div><section class="map-directory"><div>${chapters.map(c=>`<a class="chapter-row" href="#/read/${c.id}"><span class="chapter-no">${c.no}</span><div><h3>${c.label}</h3><span class="chapter-bar"><i style="width:${progress[c.id]?.percent||0}%"></i></span></div><span class="chapter-duration">${progress[c.id]?.percent?`${progress[c.id].percent}% 已读`:'未开始'}</span><b>↗</b></a>`).join('')}</div></section><section class="map-playbook"><div><h2>把方法带进酒馆</h2><p>同一种产品、相同的起点。用六次决策，看看你的判断会带来什么结果。</p></div>${link('进入增长酒馆 →','tavern','button solid')}</section><p class="editor-note">阅读主题为本项目重新编排，不等同于原书目录。</p></div>`;}
function readPage(id){const c=chapters.find(x=>x.id===id)||chapters[0];main.innerHTML=`<div class="reading-progress" id="reading-progress"></div><div class="page read-page"><div class="read-topline">${link('← 阅读地图','map')}<span>${c.no} / 06 · 约 ${c.time} 分钟</span><button class="quiet-button" data-action="reading-settings">Aa 阅读设置</button></div><div class="reading-layout"><aside class="read-index"><span class="eyebrow">本篇目录</span>${c.sections.map((s,i)=>`<a href="#section-${i}" data-scroll="section-${i}">${String(i+1).padStart(2,'0')} ${s[0]}</a>`).join('')}</aside><article class="chapter-article"><p class="eyebrow">${c.tag}</p><h1>${c.title.replace('\n','')}</h1><p class="article-intro">${c.intro}</p><blockquote><span class="quote-label">阅读提示 · 本项目撰写</span>${c.quote}</blockquote>${c.id==='activation'?'<figure class="value-figure"><img src="./assets/figma/value-platforms.png" alt="三个逐级上升的纸面平台，表现从进入到体验价值的过程" width="2172" height="724"><figcaption>进入产品 → 完成核心任务 → 体验价值 · 教学路径</figcaption></figure>':''}${c.sections.map((s,i)=>`<section class="article-section" id="section-${i}"><h2>${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}</section>`).join('')}<section class="takeaway"><p>${c.takeaway}</p><div>${link(c.action+' ↗',c.id==='growth-loop'?'cases':c.id==='economics'?'tavern':'lab','button solid')}<button class="button outline" data-action="note-from-chapter" data-id="${c.id}">写一点思考</button></div></section><div class="article-next">${c.next?link(`<span>下一条路径</span><h3>${chapters.find(x=>x.id===c.next).label} →</h3>`,`read/${c.next}`):link('<span>方法已经在手</span><h3>走进增长酒馆 →</h3>','tavern')}</div><p class="editor-note">${bookMeta.note}</p></article></div></div>`;activeReadId=c.id;suspendReading=true;const restoreScroll=progress[c.id]?.percent<100?Number(progress[c.id]?.scroll||0):0;requestAnimationFrame(()=>{window.scrollTo({left:0,top:restoreScroll,behavior:'instant'});requestAnimationFrame(()=>{suspendReading=false;updateReading();});});}
function labPage(){main.innerHTML=`<div class="page lab-page"><section class="lab-banner"><div><h1>增长实验室</h1><p>调整变量，观察三个教学模型的结果。</p></div></section><div class="lab-intro"><p>以下模型用于理解机制，不是真实产品预测。</p></div><section class="lab-experiment" id="lab-retention"><div class="experiment-label"><span>01</span><h3>先修漏桶，<br>还是先加水？</h3><p>每轮固定新增100人，初始100人。<br>观察6轮后，留存如何影响活跃规模。</p>${link('延伸阅读：留存与同期群 ↗','read/retention')}</div><div class="experiment-work"><div class="control-label"><label for="retention-input">每轮留存率</label><output id="retention-value">70%</output></div><input id="retention-input" type="range" min="10" max="95" step="5" value="70"><div id="retention-chart" class="bar-chart" role="img" aria-label="六回合活跃用户变化"></div><div class="experiment-result" id="retention-result"></div><p class="model-note">模型：下一轮活跃 = 上一轮活跃 × 留存率 + 100，逐轮取整。没有渠道、成本和人群差异，不作为经营预测。</p></div></section><section class="lab-experiment"><div class="experiment-label"><span>02</span><h3>更多流量，<br>还是更好体验？</h3><p>比较访问人数与激活率的变化，<br>看哪一环带来更多首次价值。</p>${link('延伸阅读：第一次价值 ↗','read/activation')}</div><div class="experiment-work"><div class="control-label"><label for="visitors-input">每期访问人数</label><output id="visitors-value">1,000</output></div><input id="visitors-input" type="range" min="200" max="3000" step="100" value="1000"><div class="control-label"><label for="activation-input">核心行为完成率</label><output id="activation-value">20%</output></div><input id="activation-input" type="range" min="5" max="80" step="5" value="20"><div class="conversion-flow"><div><span>访问</span><b id="conversion-visitors">1,000</b></div><i>→</i><div><span>获得首次价值</span><b id="conversion-active">200</b></div></div><div class="experiment-result" id="conversion-result"></div><p class="model-note">模型：激活人数 = 访问人数 × 完成率。这里不推断收益，也不输出统计显著性；真实实验需核对成本、样本与后续留存。</p></div></section><section class="lab-experiment"><div class="experiment-label"><span>03</span><h3>好想法很多，<br>先验证哪一个？</h3><p>用 ICE 把判断摊开讨论。<br>评分表达你的预期，不代表客观成功概率。</p>${link('延伸阅读：实验循环 ↗','read/experiments')}</div><div class="experiment-work"><div class="ice-controls">${[['impact','影响','改变有多大'],['confidence','信心','证据有多足'],['ease','便利','实施有多容易']].map(([id,name,help])=>`<div><label for="ice-${id}">${name}<small>${help}</small></label><input id="ice-${id}" type="range" min="1" max="10" value="5"><output id="ice-${id}-value">5</output></div>`).join('')}</div><div class="ice-result"><span>教学版 ICE 平均分</span><b id="ice-score">5.0</b><p id="ice-text"></p></div><p class="model-note">本项目采用(影响＋信心＋便利)÷3作为教学排序。主观评分不能替代用户研究、合规判断或真实实验。</p></div></section><section class="lab-to-tavern"><h2>现在，把这些判断<br>带到同一张桌上。</h2><p>四位经营者，同一种产品，六回合。<br>与自己的 Agent 合作，把有限资源放在你相信的事情上。</p>${link('走进 Agent 增长酒馆 ↗','tavern','button light')}<span class="small">可直接练习 · 无需读完 · 明确标识脚本席</span></section></div>`;updateLabs();}
function updateLabs(){if(!$('#retention-input'))return;let ret=+$('#retention-input').value/100,u=100;const data=Array.from({length:6},()=>u=Math.round(u*ret+100));$('#retention-value').textContent=`${Math.round(ret*100)}%`;$('#retention-chart').innerHTML=data.map((n,i)=>`<div><b>${n}</b><i style="height:${n/650*130}px"></i><span>R${i+1}</span></div>`).join('');$('#retention-result').innerHTML=`第6轮拥有 <strong>${data[5]} 位</strong>活跃用户。<span>${ret>=.8?'高留存让每一轮新增更多地沉淀下来。':ret<=.4?'新增不断进入，流失也在带走多数积累。':'留存与新增共同决定增长底座，两个入口都值得观察。'}</span>`;const v=+$('#visitors-input').value,a=+$('#activation-input').value;$('#visitors-value').textContent=num(v);$('#activation-value').textContent=a+'%';$('#conversion-visitors').textContent=num(v);$('#conversion-active').textContent=num(Math.round(v*a/100));$('#conversion-result').innerHTML=`预计 <strong>${Math.round(v*a/100)} 人</strong>完成核心行为。<span>在此模型中，完成率提高5个百分点，相当于增加${Math.round(v*.05)}位激活用户。实际投入成本仍需另算。</span>`;const vals=['impact','confidence','ease'].map(x=>{const n=+$('#ice-'+x).value;$('#ice-'+x+'-value').textContent=n;return n;});$('#ice-score').textContent=(vals.reduce((s,v)=>s+v)/3).toFixed(1);$('#ice-text').textContent=vals[1]<=3?'信心较低：先找证据，或把实验缩小到可承担的范围。':vals[2]<=3?'实施较难：先验证最关键的假设，减少一次性投入。':'适合与其他想法比较排序。先写下主指标与护栏，再开始。';}
function casePage(id){const selected=cases.find(c=>c.id===id);main.innerHTML=`<div class="page cases-page"><div class="page-heading"><div><h1>案例拆解</h1><p>三个明确标注的教学设想。<br>没有神奇秘方，只有情境、判断和后果。</p></div><div class="case-heading-art"><img src="./assets/figma/case-path.png" alt="红色折纸路径在深墨空间中分岔" width="1171" height="1343"></div></div><nav class="case-tabs" aria-label="案例选择">${cases.map(c=>`<a href="#/cases/${c.id}" ${c.id===(selected||cases[0]).id?'aria-current="page"':''}>${c.category.split(' · ')[0]}</a>`).join('')}</nav><div id="case-detail">${caseDetail(selected||cases[0])}</div></div>`;}
function caseDetail(c){return `<section class="case-layout"><aside><span class="eyebrow">${c.category}</span><h2>${c.title.replace('\n','')}</h2><p class="small muted">${c.context}</p><div class="case-route"><span>问题</span><i>↓</i><span>假设</span><i>↓</i><span>行动</span><i>↓</i><span>复盘</span></div></aside><div><div class="case-problem"><h3>我们遇到了什么？</h3><p>${c.problem}</p></div><div class="case-choice"><h3>你会先做哪一个选择？</h3><div>${c.options.map((o,i)=>`<button class="case-option" data-action="case-option" data-case="${c.id}" data-index="${i}" aria-pressed="false"><span>${String.fromCharCode(65+i)}</span><div><b>${o.name}</b><small>${o.detail}</small></div><i>→</i></button>`).join('')}</div></div><div class="case-outcome" id="case-outcome" aria-live="polite"><p>选择一个行动，看看它改变了哪一环，<br>以及哪些问题仍然没有答案。</p></div><div class="case-bottom"><p>${c.insight}</p>${link('回到知识：'+chapters.find(x=>x.id===c.chapter).label+' ↗','read/'+c.chapter)}<button class="text-link" data-action="case-note" data-id="${c.id}">把判断写进札记 +</button></div></div></section>`;}
function notesPage(id){let note=notes.find(n=>n.id===id)||null;main.innerHTML=`<div class="page notes-page"><div class="page-heading"><div><h1>阅读札记</h1><p>写下问题、证据与下一次行动。</p></div></div><div class="notes-toolbar"><p><b>${notes.length}</b> 条思考 <span class="muted">/ ${storageFailed?'内存暂存，请导出':'本机保存'}</span></p><div><button class="text-link" data-action="export-notes">导出备份 ↓</button>${getStore('trash',[]).length?'<button class="text-link" data-action="restore-note">恢复最近删除 ↶</button>':''}<label class="text-link import-label">导入恢复 ↑<input type="file" id="import-notes" accept="application/json,.json"></label><button class="button solid small-button" data-action="new-note">新增札记 +</button></div></div>${corruptedStorage?'<div class="notice error">检测到本地记录格式异常，未覆盖旧数据。可先导出原始数据备份。<button class="text-link" data-action="export-raw">导出原始数据</button></div>':''}${storageFailed?'<div class="notice error">浏览器存储不可用。当前修改仅暂存内存，关闭页面前请导出。</div>':''}<section class="notes-layout"><aside class="notes-index">${notes.length?notes.slice().sort((a,b)=>b.updated-a.updated).map(n=>`<a href="#/notes/${n.id}" ${note?.id===n.id?'aria-current="page"':''}><small>${new Date(n.updated).toLocaleDateString('zh-CN')}</small><h3>${esc(n.title||'未命名札记')}</h3><p>${esc(n.body.slice(0,46))}${n.body.length>46?'…':''}</p><span>${esc(n.tag||'自由思考')}</span></a>`).join(''):'<div class="empty-notes"><h3>第一页，留给你。</h3><p>这里没有替你写好的感悟。<br>从一个问题开始就好。</p></div>'}</aside><div class="note-editor"><form id="note-form" data-id="${note?.id||''}"><label class="sr-only" for="note-title">札记标题</label><input id="note-title" name="title" maxlength="100" placeholder="给这个想法起个名字" value="${esc(note?.title||'')}"><label for="note-tag" class="small muted">关联知识</label><select id="note-tag" name="tag"><option value="自由思考">自由思考</option>${chapters.map(c=>`<option ${note?.tag===c.tag?'selected':''}>${c.tag}</option>`).join('')}<option ${note?.tag==='酒馆复盘'?'selected':''}>酒馆复盘</option></select><label class="sr-only" for="note-body">札记正文</label><textarea id="note-body" name="body" required maxlength="20000" placeholder="我观察到的事实是……&#10;&#10;我目前的解释是……&#10;&#10;下一次，我想验证……">${esc(note?.body||'')}</textarea><div class="note-editor-bottom"><span id="note-save-status">${note?'上次保存 '+new Date(note.updated).toLocaleString('zh-CN'):'输入后点击保存。'}</span><div>${note?'<button class="quiet-button danger" type="button" data-action="delete-note" data-id="'+note.id+'">删除</button>':''}<button type="submit" class="button solid">保存札记 →</button></div></div></form><p class="small muted">建议定期导出备份。清理浏览器数据、隐私模式或更换设备可能使本地记录丢失。</p></div></section></div>`;}

async function api(path,options={}){return demoRequest(path,options);}
async function loadConfig(){if(config)return config;config=await api('/api/config');return config;}
function hostProviderLabel(god){return god?.provider==='deepseek'?'DeepSeek主持':god?.reason&&!['calls-disabled','template-mode'].includes(god.reason)?'模板主持 · 回退':'模板主持';}
async function refreshHostDisclosure(){
 const element=$('#host-disclosure');if(!element)return;
 try{const {host}=await api('/api/health');if(!element.isConnected)return;
  const message=host?.enabled?(host.lastSuccessAt?'DeepSeek 主持可用，失败时改用模板。':'已启用 DeepSeek 主持，开局后生成播报；失败时使用模板。'):host?.configuredProvider==='deepseek'&&host.keyConfigured?'DeepSeek 已配置，真实调用尚未启用，课堂Demo使用本地模板主持。':'课堂Demo使用本地模板主持。';
  element.textContent=message+'你与三位脚本对手练习，进度保存在当前浏览器。';
 }catch{if(element.isConnected)element.textContent='暂时无法确认主持连接。你与三位脚本对手练习，进度保存在当前浏览器。';}
}
function tavernLanding(){main.innerHTML=`<div class="tavern-landing"><div class="page"><section class="tavern-intro"><div class="tavern-lobby-copy"><span class="tavern-label">增长酒馆</span><h1>今晚，经营一局。</h1><p>和自己的 Agent 入席。选择行动、判断情报，在同一个市场里经营六个回合。</p><div class="tavern-principles"><span>4 个席位</span><span>6 个回合</span><span>45 秒共同决策</span></div><p class="tavern-disclosure" id="host-disclosure">正在检查主持状态。你与三位脚本对手练习，进度保存在当前浏览器。</p><a href="#/read/experiments" class="text-link">先了解实验与复盘 →</a></div><div class="tavern-entry"><div class="entry-tabs"><button class="active" data-action="entry-mode" data-mode="create">新开一桌</button><button disabled title="课堂Demo仅支持本浏览器单人练习">同桌模式待开放</button></div><form id="room-form"><input type="hidden" name="entry" value="create"><label>你的称呼<input name="name" placeholder="怎么称呼你？" maxlength="24" required autocomplete="nickname"></label><div id="join-field" hidden><label>房间代码<input name="roomId" placeholder="输入朋友分享的代码" maxlength="40"></label></div><div id="create-fields"><label>游戏模式<select name="mode"><option value="practice">单人练习 · 另3席为脚本</option></select></label></div><details class="entry-preferences"><summary>经营偏好</summary><div class="form-two"><label>性格<select name="persona"><option value="analytical">理性分析</option><option value="creative">探索创新</option><option value="pragmatic">务实经营</option></select></label><label>风险偏好<select name="risk"><option value="medium">平衡</option><option value="low">稳健</option><option value="high">进取</option></select></label></div><label>授权<select name="authorization"><option value="assist">手动决策 · 课堂Demo</option></select></label></details><button type="submit" class="button solid full">入席 →</button><p class="form-error" id="room-error" role="alert"></p><p class="entry-privacy">课堂Demo只支持手动决策，不连接外部Agent或模型，不产生模型调用费用。</p></form></div></section>${Object.keys(sessions).length?`<div class="saved-sessions"><h2>继续上次的房间</h2>${Object.entries(sessions).slice(-4).reverse().map(([id,s])=>`<a href="#/tavern/${esc(id)}"><span>${esc(s.name)}</span><b>${esc(id)} →</b></a>`).join('')}</div>`:''}</div></div>`;void refreshHostDisclosure();}
function credentials(id){return sessions[id];}
async function openRoom(id){const s=credentials(id);if(!s){main.innerHTML=`<div class="page room-missing"><h1>这张桌，<br>还没有你的席位。</h1><p>房间代码不能代替个人凭据。<br>首次加入请在入口输入代码；已有凭据可在原浏览器恢复。</p>${link('前往入席 →','tavern','button solid')}</div>`;return;}try{await loadConfig();const data=await api('/api/rooms/'+id,{token:s.token});if(location.hash!=='#/tavern/'+id)return;currentState=data.state;serverOffset=Date.now()-currentState.serverTime;renderGame(true);pollId=setInterval(()=>pollRoom(id),1000);}catch(e){main.innerHTML=`<div class="page room-missing"><h1>暂时没能<br>回到这张桌。</h1><p>${esc(e.message)}</p><button class="button solid" data-action="retry-room" data-id="${esc(id)}">重试连接 →</button>${link('返回酒馆入口','tavern')}</div>`;}}
async function pollRoom(id){if(location.hash!=='#/tavern/'+id)return;try{const d=await api('/api/rooms/'+id,{token:credentials(id)?.token});if(location.hash!=='#/tavern/'+id)return;if(currentState?.id===id&&d.state.version<currentState.version)return;const prev=currentState;currentState=d.state;serverOffset=Date.now()-currentState.serverTime;$('#connection-status')?.classList.remove('offline');if(viewKey!==`${currentState.id}-${currentState.phase}-${currentState.round}`)renderGame(true);else updateGame();}catch(e){const el=$('#connection-status');if(el){el.classList.add('offline');el.textContent='连接中断 · 正在重试';}}}
function actionName(id){return config?.actions?.find(a=>a.id===id)?.name||id||'等待选择';}
function phaseName(s){return {lobby:'等待入席',preparing:'Agent准备',decision:'共同决策',settling:'锁单结算',finished:'本局结束'}[s.phase]||s.phase;}
function gameMarkup(s){return `<div class="game-page arena roundtable-room" data-room="${esc(s.id)}"><header class="arena-hud"><div class="arena-room"><a class="arena-back" href="#/tavern" aria-label="返回酒馆">←</a><div><h1>增长酒馆</h1><button data-action="copy-room" class="room-code">${esc(s.id)} <span>复制代码</span></button></div></div><div class="arena-phase"><span id="phase-label">${s.phase==='lobby'?'等待开局':s.phase==='finished'?'六轮已完成':`第 ${s.round} / 6 回合 · ${phaseName(s)}`}</span>${['preparing','decision','settling'].includes(s.phase)?'<strong id="countdown"></strong>':''}</div><nav class="arena-toolbar" aria-label="对局工具"><button class="arena-jump" data-action="focus-action">行动</button><button data-action="edit-avatar" aria-label="更换我的头像">头像</button><button data-action="open-panel" data-panel="world">情报 <span id="world-count"></span></button><button data-action="open-panel" data-panel="research">研究 <span id="research-count"></span></button><button data-action="open-panel" data-panel="ledger">账本</button><button data-action="agent">Agent</button><button data-action="rules">规则</button><a href="#/map">阅读</a></nav></header><div class="arena-mode"><span id="connection-status">正在同步</span><span>${s.mode==='practice'?'练习房 · 另3席为脚本':'四人同桌'} · <b id="god-provider">${esc(hostProviderLabel(s.god))}</b></span></div><section class="arena-stage" aria-label="四人圆桌经营场景"><div class="arena-product"><h2>${esc(s.product?.name)}</h2><p>${esc(s.product?.coreBehavior)}</p></div><div id="globe-container" class="globe-container" aria-label="四位经营者围坐的三维圆桌"></div><div class="arena-world-peek"><button id="world-preview" data-action="open-panel" data-panel="world">开局后将发布公开情报</button></div><div class="globe-controls"><button class="icon-button" data-action="globe-out" aria-label="缩小球体">−</button><button class="icon-button" data-action="globe-in" aria-label="放大球体">＋</button><button class="quiet-button" data-action="globe-auto" aria-pressed="${autoRotate}">自转${autoRotate?'开':'关'}</button><span>拖动旋转 · 滚轮缩放</span></div></section><section class="decision-panel arena-dock" id="decision-panel" aria-label="本轮行动">${decisionMarkup(s)}</section></div>`;}
function decisionMarkup(s){const me=s.me||{},player=s.players.find(p=>p.id===me.id);
 if(s.phase==='lobby')return `<div class="dock-phase-copy"><h2>${s.players.length<4?'等朋友们入席':'准备好就开局'}</h2><p>${s.players.length} / 4 席已就位，同类产品、相同起点。</p></div><div class="dock-phase-actions">${s.hostId===me.id?`<button class="button solid" data-action="start" ${s.players.length<4?'disabled':''}>${s.players.length<4?'等待四位玩家':'开局 →'}</button>`:'<span class="notice">等待房主开始</span>'}<button class="button outline" data-action="agent">连接我的 Agent</button></div>`;
 if(s.phase==='preparing'||s.phase==='settling')return `<div class="dock-phase-copy"><h2>${s.phase==='preparing'?'先看本轮情报':'行动已锁定'}</h2><p>${s.phase==='preparing'?'准备结束后，有完整45秒共同选择窗口。':'本地规则引擎统一结算，这时不能修改行动。'}</p></div><div class="dock-phase-actions"><button class="button outline" data-action="open-panel" data-panel="world">查看情报</button>${s.mode==='practice'?'<button class="button solid" data-action="advance">练习：继续 →</button>':''}</div>`;
 if(s.phase==='finished'){const winners=s.winners||[];return `<div class="dock-phase-copy final-result"><h2>${winners.length?(winners.includes(me.id)?'你在本局榜首':'六轮经营结束'):'全员破产，本局无胜者'}</h2><p><b>${fmt(player?.score)}</b> 综合分 · 第 ${player?.rank||'—'} 名${winners.length>1?' · 同分并列':''}</p></div><div class="dock-phase-actions"><button class="button solid" data-action="save-review">保存复盘札记</button><a class="button outline" href="#/read/experiments">回到知识</a><button class="quiet-button" data-action="download-replay">导出回放</button><a class="quiet-button" href="#/tavern">再开一桌</a></div>`;}
 return `<div class="dock-status"><div id="receipt-status" class="receipt-status" aria-live="polite"></div><span id="dock-countdown" class="dock-countdown" aria-label="本轮剩余时间"></span><span id="agent-connected">${me.agentConnected?'Agent已连接':'手动决策'}</span></div><div id="suggestion-slot"></div><form id="action-form"><div class="action-fields"><label>行动<select id="action-id" name="actionId">${(config?.actions||[]).map(a=>`<option value="${a.id}" ${me.action?.id===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>目标人群<select id="action-target" name="target">${(s.product?.segments||[]).map((x,i)=>`<option value="${i}" ${me.action?.target===i?'selected':''}>${esc(typeof x==='object'?x.name||x.id:x)}</option>`).join('')}</select></label><label>投入<select id="action-scale" name="scale">${(config?.actions?.find(a=>a.id===(me.action?.id||config.actions[0]?.id))?.scales||[1]).map(v=>`<option value="${v}" ${v===(me.action?.scale||1)?'selected':''}>${v===.5?'轻量':v===1?'标准':'加码'} ×${v}</option>`).join('')}</select></label><button type="submit" class="button solid" ${player?.bankrupt?'disabled':''}>${me.action?'修改行动':'确认行动'} →</button></div><div class="action-feedback"><p id="action-description" class="action-description"></p><div id="action-estimate" class="action-estimate"></div></div><p class="form-error" id="action-error" role="alert"></p><div class="dock-secondary"><button type="button" class="quiet-button" data-action="save-default">设为超时默认</button><span id="default-description"></span><button type="button" class="quiet-button" data-action="open-panel" data-panel="intent">记录本轮想法</button>${s.mode==='practice'?'<button type="button" class="quiet-button practice-advance" data-action="advance">练习：提前结算 →</button>':''}</div></form>`;
}
function renderGame(force){const s=currentState;if(!s)return;const key=`${s.id}-${s.phase}-${s.round}`;const arena=$('.arena');if(!arena||arena.dataset.room!==s.id){globe?.destroy();dockObserver?.disconnect();main.innerHTML=gameMarkup(s);dockObserver=new ResizeObserver(()=>{const a=$('.arena'),d=$('#decision-panel');if(a&&d)a.style.setProperty('--dock-height',d.offsetHeight+'px');});dockObserver.observe($('#decision-panel'));globe=mountGlobe($('#globe-container'),s.players,{autoRotate,meId:s.me?.id,onSeatClick:openSeatDetails,onAvatarClick:player=>player?.id===currentState?.me?.id?showAvatarEditor():openSeatDetails(player),onAutoRotateChange:value=>{autoRotate=value;const b=$('[data-action=globe-auto]');if(b){b.textContent='自转'+(value?'开':'关');b.setAttribute('aria-pressed',value);}}});}else if(viewKey!==key){$('.arena-phase').innerHTML=`<span id="phase-label">${s.phase==='lobby'?'等待开局':s.phase==='finished'?'六轮已完成':`第 ${s.round} / 6 回合 · ${phaseName(s)}`}</span>${['preparing','decision','settling'].includes(s.phase)?'<strong id="countdown"></strong>':''}`;$('#decision-panel').innerHTML=decisionMarkup(s);}viewKey=key;document.body.dataset.gamePhase=s.phase;updateGame();updateActionEstimate();}
function updateGame(){const s=currentState;if(!s)return;const me=s.me||{};if($('#connection-status'))$('#connection-status').textContent='已同步';const remainingSeconds=s.deadline==null?0:Math.max(0,Math.ceil((s.deadline-(Date.now()-serverOffset))/1000));if($('#countdown')){$('#countdown').innerHTML=`${remainingSeconds}<span>秒</span>`;$('#countdown').classList.toggle('urgent',remainingSeconds<=10);}if($('#dock-countdown')){$('#dock-countdown').textContent=s.phase==='decision'?`第${s.round}轮 · 还剩${remainingSeconds}秒`:phaseName(s);$('#dock-countdown').classList.toggle('urgent',s.phase==='decision'&&remainingSeconds<=10);}
 globe?.update(s.players);
 if($('#receipt-status')){const a=me.action;$('#receipt-status').innerHTML=a?`<span class="status-dot"></span><b>已提交：${esc(actionName(a.id))}</b><span>截止前可修改</span>`:'<span class="status-dot waiting"></span><b>本轮尚未提交</b><span>超时执行已校验默认</span>';}
 if($('#action-form button[type=submit]'))$('#action-form button[type=submit]').textContent=me.action?'修改行动 →':'确认行动 →';
 if($('#default-description'))$('#default-description').textContent=me.defaultAction?`当前：${actionName(me.defaultAction.id)} ×${me.defaultAction.scale}`:'未保存默认';
 if($('#agent-connected'))$('#agent-connected').textContent=me.agentConnected?'Agent已连接':'手动决策';
 if($('#god-provider'))$('#god-provider').textContent=hostProviderLabel(s.god);
 const suggestion=me.suggestion;if($('#suggestion-slot'))$('#suggestion-slot').innerHTML=suggestion?`<div class="agent-suggestion"><b>Agent建议：${esc(actionName(suggestion.action?.id||suggestion.id))}</b><p>${esc(suggestion.summary||'核对行动、目标与投入后确认。')}</p><button class="quiet-button" data-action="accept-suggestion">采用建议 →</button></div>`:'';
 const latest=(s.world||[]).slice().reverse().find(w=>w.type==='fact')||s.world?.at(-1);if($('#world-preview'))$('#world-preview').textContent=latest?latest.text:s.phase==='lobby'?'首轮结算后，球面领地开始生长。':'本轮公开情报已同步，打开查看 →';
 if($('#world-count'))$('#world-count').textContent=s.world?.length||'';if($('#research-count'))$('#research-count').textContent=me.privateNotes?.length||'';
 updatePanel(s);
 if(s.phase==='lobby'&&$('#decision-panel')&&$('#decision-panel').dataset.players!==String(s.players.length)){$('#decision-panel').innerHTML=decisionMarkup(s);$('#decision-panel').dataset.players=String(s.players.length);}
}
function updatePanel(s){const me=s.me||{};if($('#god-narration'))$('#god-narration').textContent=s.god?.text||'模板主持已就位。';
 if($('#world-feed')){const types={fact:'事实',forecast:'有限预告',rumor:'未核实传闻',verification:'核验结果'};$('#world-feed').innerHTML=(s.world||[]).slice().reverse().map(w=>`<article class="world-message ${esc(w.type)}"><header><span class="world-type">${types[w.type]||'播报'}</span><span>第${w.round||0}轮</span></header><p>${esc(w.text)}</p></article>`).join('')||'<p>开局后发布公开情报。</p>';}
 if($('#private-insights')){const notes=Array.isArray(me.privateNotes)?me.privateNotes:[];$('#private-insights').innerHTML=notes.length?notes.slice().reverse().map(n=>`<article class="research-result"><p>第${n.round}轮 · ${n.type==='research'?'用户访谈':'对照实验'} · ${esc(s.product.segments[n.target])}</p>${n.type==='research'?`<h3>引导响应 ${fmt(n.onboarding)}<br>习惯响应 ${fmt(n.habit)}</h3>`:`<h3>${esc(n.verdict)}</h3><p>差值 ${fmt(n.difference*100)} 个百分点；对照 ${n.controlSuccess}/${n.controlN}，实验 ${n.treatmentSuccess}/${n.treatmentN}；保守区间 [${fmt(n.interval?.[0]*100)}, ${fmt(n.interval?.[1]*100)}]</p>`}<p>${esc(n.text)}</p></article>`).join(''):'<p class="panel-empty">执行用户调研或对照实验后，本人的结果会出现在这里。其他席位无法读取。</p>';}
 if($('#round-history'))$('#round-history').innerHTML=s.history?.length?`<div class="history-table-wrap"><table><thead><tr><th>回合</th>${s.players.map(p=>`<th>${esc(p.name)}</th>`).join('')}</tr></thead><tbody>${s.history.map(h=>`<tr><th>${h.round}</th>${s.players.map(p=>{const r=h.players?.find(x=>x.id===p.id||x.seat===p.seat)||{};return `<td><b>${fmt(r.score)}</b><span>用户 ${num(r.users)}</span><span>利润 ${num(r.profit)}</span></td>`;}).join('')}</tr>`).join('')}</tbody></table></div>`:'<p class="panel-empty">首轮结算后显示账本。</p>';
 if($('#seat-detail')){const player=s.players.find(p=>p.id===$('#seat-detail').dataset.id);if(player)$('#seat-detail').innerHTML=seatDetail(player,s);}
}
function openSeatDetails(player){const p=currentState?.players.find(item=>item.id===player?.id);if(p)modal(p.name,`<div id="seat-detail" data-id="${esc(p.id)}">${seatDetail(p,currentState)}</div>`);}
function seatDetail(p,s){return `<div class="seat-detail-score"><b>${fmt(p.score)}</b><span>综合分 · 第 ${p.rank||'—'} 名${p.bankrupt?' · 已破产':''}</span></div><dl class="seat-detail-grid"><div><dt>有效用户</dt><dd>${num(p.users)}</dd></div><div><dt>累计利润</dt><dd>${num(p.profit)}</dd></div><div><dt>现金</dt><dd>${num(p.cash)}</dd></div><div><dt>合并留存</dt><dd>${Math.round(p.retention*100)}%</dd></div></dl><h3>分项贡献</h3><p>规模 ${fmt(p.contributions?.growth)} · 利润 ${fmt(p.contributions?.profit)} · 留存 ${fmt(p.contributions?.retention)}</p>${p.id===s.me?.id?'<button class="button outline" data-action="edit-avatar">更换我的头像</button>':''}<p class="panel-explainer">全球面积按本席分数÷（600＋全员分数合计）分配，包含背面。建筑和光晕不加分，也不代表真实市场份额。</p>`;}
function savedAvatarPreference(){
 const value=getStore('avatarPreference',null);if(value==null)return null;
 try{return normalizeAvatar(value);}catch{return null;}
}
function showAvatarEditor(){
 const s=currentState;if(!s?.me)return;
 const player=s.players.find(p=>p.id===s.me.id);if(!player)return;
 avatarEditor?.close();if($('#modal').open)$('#modal').close();
 const id=s.id,credential=credentials(id)?.token;
 let editor;
 editor=openAvatarEditor({current:player.avatar,seatIndex:player.seat,onClose:()=>{if(avatarEditor===editor)avatarEditor=null;},onSave:async avatar=>{
  const d=await api('/api/rooms/'+id+'/avatar',{method:'POST',token:credential,body:{avatar}});
  saveStore('avatarPreference',avatar);
  if(d.state&&location.hash==='#/tavern/'+id&&currentState?.id===id&&d.state.version>=currentState.version){currentState=d.state;updateGame();}
  toast('头像已更新，同桌玩家也能看到。');
 }});
 avatarEditor=editor;
}
function openGamePanel(panel){const s=currentState;if(!s)return;const titles={world:'世界情报',research:'我的研究',ledger:'经营账本',intent:'记录本轮想法'};const content={world:'<div id="god-narration" class="god-narration"></div><div id="world-feed" class="world-feed"></div>',research:'<div id="private-insights"></div>',ledger:'<p>每格先显示综合分，下方是用户与累计利润。</p><div id="round-history"></div>',intent:`<form id="intent-form"><label for="intent-text">你的经营意图</label><textarea id="intent-text" name="text" maxlength="1000" placeholder="例如：保留现金，优先修复留存……">${esc(s.me.intent?.text||s.me.intent||'')}</textarea><p>可记录本轮想法。课堂Demo不连接外部Agent，仍需手动选择行动。</p><button class="button solid" type="submit">保存给 Agent</button></form>`};modal(titles[panel]||'对局信息',content[panel]||'');$('#modal').dataset.panel=panel;updatePanel(s);}

function selectedAction(){return {id:$('#action-id')?.value,target:Number($('#action-target')?.value||0),scale:Number($('#action-scale')?.value||1)};}
function updateActionEstimate(){if(!$('#action-id'))return;const a=config.actions.find(a=>a.id===$('#action-id').value);const scaleSelect=$('#action-scale');if(scaleSelect.dataset.action!==a.id){const old=Number(scaleSelect.value);scaleSelect.innerHTML=(a.scales||[1]).map(v=>`<option value="${v}" ${v===(a.scales.includes(old)?old:1)?'selected':''}>${v===.5?'轻量':v===1?'标准':'加码'} ×${v}</option>`).join('');scaleSelect.dataset.action=a.id;}const targetSelect=$('#action-target');targetSelect.disabled=a.scope==='all';if(a.scope==='all')targetSelect.value='0';$('#action-description').textContent=(typeof a?.effect==='string'?a.effect:a?.concept)||'选择一项合法行动，查看预算后提交。';const cost=typeof a?.cost==='number'?a.cost:0;const scale=Number($('#action-scale').value);const player=currentState.players.find(p=>p.id===currentState.me.id);$('#action-estimate').innerHTML=`<span>行动投入 <b>${num(cost*scale)}</b></span><span>现金 <b>${num(player?.cash)}</b>（保留20运营费）</span>`;}

function modal(title,html){const el=$('#modal');el.dataset.panel='';el.innerHTML=`<div class="modal-header"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">×</button></div><div class="modal-body">${html}</div>`;if(!el.open)el.showModal();}
function agentPrompt(){const s=currentState,c=credentials(s.id);return `你是增长酒馆里我自己的玩家Agent，只能访问我这一席。服务地址：${location.origin}\n房间：${s.id}\nAgent Bearer token：${c.agentToken}\n\n先 GET /api/rooms/${s.id}/agent/check 完成连接自检，然后 GET /api/rooms/${s.id}/agent/state 读取状态与我的意图，GET /api/config 查看12种行动。请求头 Authorization: Bearer <上述token>。不要读取其他本机文件或聊天，不索要供应商密钥。\n\n每轮只映射一项合法行动：POST /api/rooms/${s.id}/agent/action，JSON {"round":当前回合,"action":{"id":"A01","target":0,"scale":1},"requestId":"每次决策唯一ID","summary":"解释行动、目标、投入与风险"}。assist模式提交建议等待我确认；autopilot模式直接行动。行动须符合预算、席位、回合与本地演示截止时间。读取提交回执，不把请求发送当作成功。使用inbox?since=cursor持续读取我的新意图和公开状态；断线后读取状态恢复，重试保留同一requestId。不创造机制、不组合多次行动、不访问未来事件或对手私有信息。每轮先看事实与未核实传闻的区别。${s.me.persona?`我的性格：${s.me.persona}；风险：${s.me.risk}。`:''}\n\n请先报告连接自检结果。复制这段提示词本身不代表已建立双向连接。`}
async function act(action,body={}){const id=currentState.id;const d=await api('/api/rooms/'+id+'/'+action,{method:'POST',token:credentials(id).token,body});if(d.state&&location.hash==='#/tavern/'+id&&(!currentState||d.state.version>=currentState.version)){currentState=d.state;if(viewKey!==`${currentState.id}-${currentState.phase}-${currentState.round}`)renderGame(true);else updateGame();}return d;}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function newNote(data={}){const n={id:uid(),title:'',body:'',tag:'自由思考',created:Date.now(),updated:Date.now(),...data};notes.push(n);saveStore('notes',notes);go('notes/'+n.id);}
async function actions(el){const action=el.dataset.action;try{switch(action){
 case 'close-modal':$('#modal').close();break;
 case 'open-panel':openGamePanel(el.dataset.panel);break;
 case 'focus-action':{const d=$('#decision-panel');d.setAttribute('tabindex','-1');d.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});d.focus({preventScroll:true});break;}
 case 'seat-detail':openSeatDetails(currentState?.players.find(p=>p.id===el.dataset.id));break;
 case 'edit-avatar':showAvatarEditor();break;
 case 'new-note':newNote();break;
 case 'note-from-chapter':{const c=chapters.find(c=>c.id===el.dataset.id);newNote({title:c.tag+' · 我的思考',tag:c.tag,body:'读到这里，我想到：\n\n我观察到的事实：\n\n下一次想验证：'});break;}
 case 'case-note':{const c=cases.find(c=>c.id===el.dataset.id);newNote({title:c.category+' · 策略判断',tag:chapters.find(x=>x.id===c.chapter).tag,body:'教学情境：'+c.problem+'\n\n'+(caseSelections[c.id]!==undefined?'已选行动：'+c.options[caseSelections[c.id]].name+'\n机制分析（教学设想）：'+c.options[caseSelections[c.id]].result+'\n\n':'')+'我的理由：\n\n还需要哪些证据：'});break;}
 case 'delete-note':modal('删除这条札记？','<p>删除会移入本机恢复区，保留最近20条。</p><button class="button solid" data-action="confirm-delete-note" data-id="'+el.dataset.id+'">确认删除</button>');break;
 case 'confirm-delete-note':{const n=notes.find(n=>n.id===el.dataset.id);saveStore('trash',[n,...getStore('trash',[])].slice(0,20));notes=notes.filter(n=>n.id!==el.dataset.id);saveStore('notes',notes);$('#modal').close();go('notes');toast('已移入恢复区。可通过“导入恢复”或备份恢复。');break;}
 case 'restore-note':{const trash=getStore('trash',[]);const n=trash.shift();if(n&&!notes.some(x=>x.id===n.id)){notes.push(n);saveStore('notes',notes);}saveStore('trash',trash);go('notes/'+(n?.id||''));toast('已恢复最近删除的札记。');break;}
 case 'export-raw':download('增长札记-原始存储备份.json',{badStorage,rawNotes,rawProgress,rawSessions});break;
 case 'export-notes':download('增长札记-'+new Date().toISOString().slice(0,10)+'.json',{version:1,exportedAt:new Date().toISOString(),notes,trash:getStore('trash',[])});toast('札记备份已导出。');break;
 case 'case-option':{const c=cases.find(c=>c.id===el.dataset.case),o=c.options[+el.dataset.index];caseSelections[c.id]=+el.dataset.index;document.querySelectorAll('.case-option').forEach(x=>x.setAttribute('aria-pressed',String(x===el)));$('#case-outcome').innerHTML=`<h3>${o.metric}</h3><p>${o.result}</p><small>这是机制分析，不是已发生的经营结果。</small>`;break;}
 case 'reading-settings':modal('让阅读舒服一点',`<label>正文字号<input type="range" id="font-size" min="16" max="23" value="${getStore('fontSize',matchMedia('(max-width:680px)').matches?17:18)}"></label><p>修改仅影响阅读正文。</p><button class="button outline" data-action="complete-reading">标记当前篇已读 →</button>`);break;
 case 'complete-reading':{const id=location.hash.split('/')[2];progress[id]={percent:100,scroll:0,updated:Date.now()};saveStore('progress',progress);$('#modal').close();toast('本篇已标记为已读。');break;}
 case 'entry-mode':{const join=el.dataset.mode==='join';$('#room-form').elements.entry.value=join?'join':'create';$('#join-field').hidden=!join;$('#create-fields').hidden=join;document.querySelectorAll('.entry-tabs button').forEach(b=>b.classList.toggle('active',b===el));$('#room-form').elements.roomId.required=join;break;}
 case 'retry-room':await openRoom(el.dataset.id);break;
 case 'copy-room':await navigator.clipboard.writeText(currentState.id);toast('练习编号已复制；本Demo不支持跨浏览器加入。');break;
 case 'start':await act('start');toast('第一回合开始。');break;
 case 'advance':await act('advance');toast(currentState.phase==='finished'?'六回合已完成。':'已结算，进入下一回合。');break;
 case 'save-default':await act('default',{action:selectedAction()});toast('已校验并保存超时默认。');break;
 case 'accept-suggestion':{const a=currentState.me.suggestion?.action||currentState.me.suggestion;await act('action',{round:currentState.round,action:a,requestId:uid()});toast('已确认Agent建议。');break;}
 case 'agent':modal('课堂 Demo 的玩家席位','<p>本版在浏览器中运行完整经营引擎，你手动决策，另外三席是明确标注的脚本对手。</p><p>线上Demo没有服务端密钥，不连接真实外部Agent或DeepSeek。书籍、实验、照片头像与六轮经营都可以体验。</p>');break;
 case 'copy-agent':await navigator.clipboard.writeText($('#agent-prompt').value);toast('接入指令已复制；请由Agent执行连接自检。');break;
 case 'rotate-agent':{const d=await act('agent/rotate');sessions[currentState.id].agentToken=d.agentToken;saveStore('sessions',sessions);$('#agent-prompt').value=agentPrompt();toast('旧Agent凭据已撤销。');break;}
 case 'rules':modal('把规则摊在桌上',`<p>四席 · 六回合 · 每轮45秒共同选择窗口。每轮只执行一个合法行动，截止前可修改，截止后不可改写。</p><h3>唯一综合分</h3><p>规模50%＋累计利润35%＋留存15%。归一化与预算采用本局绑定的规则版本 <b>${esc(currentState.rules?.version||'growth-v1')}</b>。</p><p>规模分＝500×U÷(U＋450)，U为最近最多3轮有效用户均值；利润分＝350×[0.5＋0.5×P÷(|P|＋1200)]，P为累计利润；留存分＝150×最近最多3轮保留用户合计÷对应上轮用户合计。总分四舍五入到两位小数；破产归零。同分并列；全员破产无胜者。</p><details><summary>查看本局规则原文</summary><pre>${esc(JSON.stringify(currentState.rules,null,2))}</pre></details><h3>结算顺序与边界</h3><p>先锁定行动与预算，再应用事件与行动；计算留存和触达、按共享市场分配新用户，最后结算收入、行动成本与运营成本，更新现金、破产与综合分。每轮保留20固定运营费；预算不足的行动由本地规则引擎拒绝。</p><h3>你的权限与默认</h3><p>网页与Agent只访问自己获准的信息。无合法超时默认时等待，不暗中替你增加行动。自由意图需自己的Agent映射；手动操作直接选择行动。</p><h3>情报与主持</h3><p>事实、有限预告、未核实传闻与核验分开。主持不改分，不裁定胜负；模板模式可完整玩一局。</p>`);break;
 case 'globe-in':globe?.zoomIn?.();break;
 case 'globe-out':globe?.zoomOut?.();break;
 case 'globe-auto':autoRotate=!autoRotate;globe?.setAutoRotate(autoRotate);el.textContent='自动旋转 '+(autoRotate?'开':'关');el.setAttribute('aria-pressed',autoRotate);break;
 case 'save-review':{const s=currentState,p=s.players.find(p=>p.id===s.me.id);newNote({title:`${s.product.name} · 六轮经营复盘`,tag:'酒馆复盘',body:`房间：${s.id}\n规则版本：${s.rules?.version||'growth-v1'}\n最终综合分：${fmt(p.score)}，第${p.rank}名\n用户：${fmt(p.users)}；利润：${fmt(p.profit)}；留存：${Math.round(p.retention*100)}%\n\n已确认事实：\n${s.history.map(h=>{const q=h.players.find(x=>x.id===p.id||x.seat===p.seat);return `R${h.round}：综合分${fmt(q?.score)}，用户${fmt(q?.users)}，利润${fmt(q?.profit)}`;}).join('\n')}\n\n我的解释（需要区分机制与随机影响）：\n\n下一局要验证的假设：`});break;}
 case 'download-replay':{const d=await api('/api/rooms/'+currentState.id+'/replay',{token:credentials(currentState.id).token});download('增长酒馆-回放-'+currentState.id+'.json',d.replay);toast('已导出回放。');break;}
 }}catch(e){toast(e.message,true);}}

document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a){e.preventDefault();actions(a);}const scroll=e.target.closest('[data-scroll]');if(scroll){e.preventDefault();document.getElementById(scroll.dataset.scroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
document.addEventListener('input',e=>{if(e.target.closest('.lab-page'))updateLabs();if(e.target.id==='font-size'){document.documentElement.style.setProperty('--reading-size',e.target.value+'px');saveStore('fontSize',+e.target.value);}if(['action-id','action-scale','action-target'].includes(e.target.id))updateActionEstimate();});
document.addEventListener('change',async e=>{if(e.target.id==='import-notes'){try{const file=e.target.files[0];if(!file)return;if(file.size>4e6)throw new Error('备份文件过大，请使用4MB以内的JSON。');const data=JSON.parse(await file.text());if(!Array.isArray(data.notes)||data.notes.some(n=>!safeId(n.id)||typeof n.body!=='string'||typeof n.title!=='string'))throw new Error('不是有效的札记备份。');const map=new Map(notes.map(n=>[n.id,n]));for(const n of data.notes){if(!map.has(n.id)||n.updated>map.get(n.id).updated)map.set(n.id,{id:String(n.id),title:n.title.slice(0,100),body:n.body.slice(0,20000),tag:String(n.tag||'自由思考'),created:Number(n.created)||Date.now(),updated:Number(n.updated)||Date.now()});}notes=[...map.values()];saveStore('notes',notes);render();toast('备份已合并恢复。');}catch(err){toast(err.message,true);}}});
document.addEventListener('submit',async e=>{const form=e.target;e.preventDefault();if(form.id==='note-form'){const values=new FormData(form);const n=notes.find(n=>n.id===form.dataset.id)||{id:uid(),created:Date.now()};n.title=String(values.get('title')).trim()||'未命名札记';n.body=String(values.get('body')).trim();n.tag=String(values.get('tag'));n.updated=Date.now();if(!n.body){toast('写一点内容，再保存。',true);return;}if(!notes.includes(n))notes.push(n);const saved=saveStore('notes',notes);go('notes/'+n.id);toast(saved?'札记已保存到此浏览器。':'已暂存内存，请导出备份。',!saved);}
 if(form.id==='room-form'){const b=form.querySelector('button[type=submit]');b.disabled=true;$('#room-error').textContent='';try{const v=Object.fromEntries(new FormData(form));const join=v.entry==='join';const payload={name:v.name,persona:v.persona,risk:v.risk,authorization:v.authorization,...(!join?{mode:v.mode}:{})};const d=await api(join?'/api/rooms/'+encodeURIComponent(v.roomId.trim())+'/join':'/api/rooms',{method:'POST',body:payload});sessions[d.roomId]={token:d.token,agentToken:d.agentToken,playerId:d.playerId,name:v.name};saveStore('sessions',sessions);let avatarWarning=false;const preference=savedAvatarPreference();if(preference)try{await api('/api/rooms/'+d.roomId+'/avatar',{method:'POST',token:d.token,body:{avatar:preference}});}catch{avatarWarning=true;}go('tavern/'+d.roomId);if(avatarWarning)toast('已入席；上次头像未能应用，可在桌边重新选择。',true);}catch(err){$('#room-error').textContent=err.message;b.disabled=false;}}
 if(form.id==='action-form'){const b=form.querySelector('button[type=submit]');b.disabled=true;$('#action-error').textContent='';try{await act('action',{round:currentState.round,action:selectedAction(),requestId:uid()});toast('行动已收到本地规则引擎回执，截止前可修改。');}catch(err){$('#action-error').textContent=err.message;}finally{if(b.isConnected)b.disabled=false;}}
 if(form.id==='profile-form'){try{await act('profile',Object.fromEntries(new FormData(form)));if($('#agent-prompt'))$('#agent-prompt').value=agentPrompt();toast('Agent性格、风险与授权已保存。');}catch(err){toast(err.message,true);}}
 if(form.id==='intent-form'){try{await act('intent',{text:new FormData(form).get('text')});$('#modal').close();toast('想法已保存在本浏览器，请手动提交行动。');}catch(err){toast(err.message,true);}}
});
function updateReading(){if(!activeReadId||suspendReading)return;const id=activeReadId,article=$('.chapter-article');if(!article)return;const total=Math.max(1,article.offsetTop+article.offsetHeight-innerHeight);const pct=Math.min(100,Math.max(0,Math.round(scrollY/total*100)));if($('#reading-progress'))$('#reading-progress').style.width=pct+'%';progress[id]={percent:Math.max(progress[id]?.percent||0,pct),scroll:scrollY,updated:Date.now()};clearTimeout(updateReading.timer);updateReading.timer=setTimeout(()=>saveStore('progress',progress),500);}
window.addEventListener('scroll',updateReading,{passive:true});window.addEventListener('pagehide',()=>{if(activeReadId&&!suspendReading){updateReading();clearTimeout(updateReading.timer);saveStore('progress',progress);}});
async function render(){avatarEditor?.close();avatarEditor=null;if(activeReadId&&!suspendReading){updateReading();clearTimeout(updateReading.timer);saveStore('progress',progress);}activeReadId=null;suspendReading=false;const parts=(location.hash.replace(/^#\/?/,'')||'home').split('/');route=parts[0];clearInterval(pollId);pollId=null;dockObserver?.disconnect();dockObserver=null;globe?.destroy();globe=null;viewKey='';currentState=null;$('#modal').open&&$('#modal').close();document.body.classList.toggle('night',route==='tavern');document.body.classList.toggle('in-game',route==='tavern'&&!!parts[1]);header(route);footer();window.scrollTo({left:0,top:0,behavior:'instant'});const savedFontSize=Number(getStore('fontSize',null));if(savedFontSize>=16&&savedFontSize<=23)document.documentElement.style.setProperty('--reading-size',savedFontSize+'px');else document.documentElement.style.removeProperty('--reading-size');switch(route){case 'home':home();break;case 'map':mapPage();break;case 'read':readPage(parts[1]);break;case 'lab':labPage();break;case 'cases':casePage(parts[1]);break;case 'notes':notesPage(parts[1]);break;case 'tavern':if(parts[1]){main.innerHTML='<div class="page loading-state"><h1>正在连接房间</h1><p>恢复你的席位与对局状态……</p></div>';await openRoom(decodeURIComponent(parts[1]));}else tavernLanding();break;default:home();}document.title=(route==='tavern'?'Agent 增长酒馆':route==='read'?(chapters.find(c=>c.id===parts[1])?.label||'章节阅读'):{home:'一本可以亲自验证的书',map:'阅读地图',lab:'增长实验室',cases:'案例拆解',notes:'阅读札记'}[route]||'增长黑客')+' · 增长黑客';}
window.addEventListener('hashchange',render);render();
